app_css:
.tool-app-hoodcadence { color: #431407; max-width: 900px; margin-inline: auto; }
.tool-app-hoodcadence .hc-intro { display: grid; grid-template-columns: 1fr 300px; gap: 18px; align-items: start; margin: 14px 0; }
.tool-app-hoodcadence .hc-title { font-size: 22px; margin: 0 0 8px; color: #431407; }
.tool-app-hoodcadence .hc-lede { margin: 0; font-size: 14px; color: #7c2d12; line-height: 1.55; }
.tool-app-hoodcadence .hc-intro-rule { background: #fff7ed; border: 1px solid #fed7aa; border-radius: 12px; padding: 12px 14px; font-size: 13px; }
.tool-app-hoodcadence .hc-intro-rule strong { display: block; margin-bottom: 6px; font-size: 13px; }
.tool-app-hoodcadence .hc-intro-rule ul { list-style: none; margin: 0; padding: 0; }
.tool-app-hoodcadence .hc-intro-rule li { display: flex; justify-content: space-between; padding: 3px 0; }
.tool-app-hoodcadence .hc-toolbar { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; margin: 6px 0 14px; }
.tool-app-hoodcadence .hc-btn { background: #EA580C; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-hoodcadence .hc-btn:hover { background: #c2410c; }
.tool-app-hoodcadence .hc-btn-ghost { background: #fff7ed; color: #c2410c; border: 1px solid #fed7aa; }
.tool-app-hoodcadence .hc-btn-ghost:hover { background: #ffedd5; }
.tool-app-hoodcadence .hc-counts { display: flex; gap: 8px; margin-left: auto; }
.tool-app-hoodcadence .hc-pill { background: #f5f5f4; border-radius: 999px; padding: 6px 12px; font-size: 13px; }
.tool-app-hoodcadence .hc-pill b { font-weight: 800; }
.tool-app-hoodcadence .hc-pill-overdue { background: #fef2f2; color: #b91c1c; }
.tool-app-hoodcadence .hc-pill-due { background: #fffbeb; color: #b45309; }
.tool-app-hoodcadence .hc-formwrap { background: #fff7ed; border: 1px solid #fed7aa; border-radius: 12px; padding: 16px; margin-bottom: 14px; }
.tool-app-hoodcadence .hc-h3 { margin: 0 0 10px; font-size: 16px; }
.tool-app-hoodcadence form { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 10px; }
.tool-app-hoodcadence label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-hoodcadence input[type="text"], .tool-app-hoodcadence input[type="number"], .tool-app-hoodcadence input[type="date"], .tool-app-hoodcadence select, .tool-app-hoodcadence textarea { border: 1px solid #fdba74; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; }
.tool-app-hoodcadence .hc-form-actions { grid-column: 1 / -1; display: flex; gap: 10px; }
.tool-app-hoodcadence .hc-table { width: 100%; border-collapse: collapse; margin: 6px 0; font-size: 14px; }
.tool-app-hoodcadence .hc-table th { text-align: left; font-size: 12px; color: #9a3412; padding: 6px; }
.tool-app-hoodcadence .hc-table td { padding: 8px 6px; border-top: 1px solid #fed7aa; vertical-align: middle; }
.tool-app-hoodcadence .hc-site b { display: block; }
.tool-app-hoodcadence .hc-site small { color: #9a3412; }
.tool-app-hoodcadence .hc-status { font-weight: 700; font-size: 13px; border-radius: 999px; padding: 4px 10px; white-space: nowrap; }
.tool-app-hoodcadence .hc-st-overdue { background: #fef2f2; color: #b91c1c; }
.tool-app-hoodcadence .hc-st-due { background: #fffbeb; color: #b45309; }
.tool-app-hoodcadence .hc-st-ok { background: #f0fdf4; color: #15803d; }
.tool-app-hoodcadence .hc-rowbtns { white-space: nowrap; }
.tool-app-hoodcadence .hc-rowbtns button { background: none; border: 1px solid #fdba74; border-radius: 8px; padding: 5px 10px; font-size: 12px; font-weight: 700; cursor: pointer; color: #c2410c; margin-right: 6px; }
.tool-app-hoodcadence .hc-rowbtns button:hover { background: #fff7ed; }
.tool-app-hoodcadence .hc-empty { text-align: center; color: #9a3412; padding: 26px 0; font-size: 14px; }
.tool-app-hoodcadence .tool-print-doc { display: none; }
@media (max-width: 640px) {
  .tool-app-hoodcadence .hc-intro { grid-template-columns: 1fr; }
  .tool-app-hoodcadence .hc-counts { margin-left: 0; }
}
@media print {
  .tool-app-hoodcadence .hc-screen { display: none !important; }
  .tool-app-hoodcadence .tool-print-doc { display: block !important; color: #000; }
  .tool-app-hoodcadence .tool-print-doc h1 { font-size: 22px; margin: 0 0 4px; }
  .tool-app-hoodcadence .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-hoodcadence .tool-print-doc th, .tool-app-hoodcadence .tool-print-doc td { border: 1px solid #999; padding: 8px; text-align: left; font-size: 14px; }
}

app_js:
(function () {
  'use strict';
  var CADENCE = {
    solid:    { name: 'Monthly',     months: 1  },
    high:     { name: 'Quarterly',   months: 3  },
    moderate: { name: 'Semi-annual', months: 6  },
    low:      { name: 'Annual',      months: 12 }
  };
  var TYPE_LABEL = {
    solid: 'Solid fuel', high: 'High volume', moderate: 'Moderate volume', low: 'Low volume'
  };
  var LS = 'toolapp-hoodcadence-sites';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function parseDate(s) {
    var p = String(s || '').split('-');
    if (p.length !== 3) return null;
    var d = new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10));
    return isNaN(d.getTime()) ? null : d;
  }
  function fmt(d) {
    return (d.getMonth() + 1) + '/' + d.getDate() + '/' + d.getFullYear();
  }
  function iso(d) {
    var m = d.getMonth() + 1, day = d.getDate();
    return d.getFullYear() + '-' + (m < 10 ? '0' + m : m) + '-' + (day < 10 ? '0' + day : day);
  }
  function nextDue(lastIso, type) {
    var last = parseDate(lastIso);
    if (!last) return null;
    var d = new Date(last.getFullYear(), last.getMonth() + CADENCE[type].months, last.getDate());
    return d;
  }
  function daysUntil(d) {
    var now = new Date(); now.setHours(0, 0, 0, 0);
    var t = new Date(d); t.setHours(0, 0, 0, 0);
    return Math.round((t.getTime() - now.getTime()) / 864e5);
  }
  function getSites() {
    try { return JSON.parse(localStorage.getItem(LS)) || []; } catch (e) { return []; }
  }
  function setSites(s) {
    try { localStorage.setItem(LS, JSON.stringify(s)); } catch (e) {}
  }
  function statusOf(site) {
    var due = nextDue(site.last, site.type);
    if (!due) return { key: 'ok', label: 'No date', due: null, days: null };
    var days = daysUntil(due);
    if (days < 0) return { key: 'overdue', label: 'Overdue ' + (-days) + 'd', due: due, days: days };
    if (days <= 14) return { key: 'due', label: 'Due in ' + days + 'd', due: due, days: days };
    return { key: 'ok', label: 'Current', due: due, days: days };
  }
  function render() {
    var sites = getSites();
    sites.sort(function (a, b) {
      var da = nextDue(a.last, a.type), db = nextDue(b.last, b.type);
      if (!da && !db) return 0;
      if (!da) return 1;
      if (!db) return -1;
      return da.getTime() - db.getTime();
    });
    var tb = $('hc-rows');
    tb.innerHTML = '';
    var nOver = 0, nDue = 0;
    sites.forEach(function (s) {
      var st = statusOf(s);
      if (st.key === 'overdue') nOver++;
      if (st.key === 'due') nDue++;
      var tr = document.createElement('tr');
      var tdSite = document.createElement('td');
      tdSite.className = 'hc-site';
      tdSite.innerHTML = '<b>' + esc(s.name) + '</b><small>' + esc(TYPE_LABEL[s.type] || s.type) + (s.contact ? ' &middot; ' + esc(s.contact) : '') + '</small>';
      var tdCad = document.createElement('td'); tdCad.textContent = CADENCE[s.type].name;
      var tdLast = document.createElement('td');
      var last = parseDate(s.last);
      tdLast.textContent = last ? fmt(last) : '-';
      var tdDue = document.createElement('td');
      tdDue.textContent = st.due ? fmt(st.due) : '-';
      var tdSt = document.createElement('td');
      var pill = document.createElement('span');
      pill.className = 'hc-status hc-st-' + st.key;
      pill.textContent = st.label;
      tdSt.appendChild(pill);
      var tdAct = document.createElement('td');
      tdAct.className = 'hc-rowbtns';
      tdAct.innerHTML =
        '<button type="button" data-act="cleaned" data-id="' + s.id + '">Mark cleaned</button>' +
        '<button type="button" data-act="edit" data-id="' + s.id + '">Edit</button>' +
        '<button type="button" data-act="del" data-id="' + s.id + '" aria-label="Delete site">&times;</button>';
      tr.appendChild(tdSite); tr.appendChild(tdCad); tr.appendChild(tdLast);
      tr.appendChild(tdDue); tr.appendChild(tdSt); tr.appendChild(tdAct);
      tb.appendChild(tr);
    });
    $('hc-n-overdue').textContent = nOver;
    $('hc-n-due').textContent = nDue;
    $('hc-empty').style.display = sites.length ? 'none' : '';
  }
  function openForm(site) {
    $('hc-formwrap').hidden = false;
    $('hc-reportwrap').hidden = true;
    if (site) {
      $('hc-id').value = site.id;
      $('hc-name').value = site.name || '';
      $('hc-contact').value = site.contact || '';
      $('hc-phone').value = site.phone || '';
      $('hc-type').value = site.type || 'moderate';
      $('hc-last').value = site.last || '';
      $('hc-price').value = site.price || 0;
    } else {
      $('hc-form').reset();
      $('hc-id').value = '';
      $('hc-type').value = 'moderate';
      $('hc-last').value = iso(new Date());
    }
    $('hc-name').focus();
  }
  function findSite(id) {
    var sites = getSites();
    for (var i = 0; i < sites.length; i++) if (sites[i].id === id) return sites[i];
    return null;
  }
  function newId() { return 's' + Date.now().toString(36) + Math.floor(Math.random() * 9999); }
  function openReport() {
    var sites = getSites();
    if (!sites.length) { alert('Add a site first, then print a service report.'); return; }
    var sel = $('hc-rep-site');
    sel.innerHTML = '';
    sites.forEach(function (s) {
      var o = document.createElement('option');
      o.value = s.id;
      o.textContent = s.name;
      sel.appendChild(o);
    });
    $('hc-reportwrap').hidden = false;
    $('hc-formwrap').hidden = true;
    $('hc-rep-date').value = iso(new Date());
    if (!$('hc-rep-cert').value) {
      $('hc-rep-cert').value = 'HC-' + new Date().getFullYear() + '-' + String(Math.floor(1000 + Math.random() * 9000));
    }
  }
  function printReport() {
    var site = findSite($('hc-rep-site').value);
    if (!site) return;
    var due = nextDue($('hc-rep-date').value, site.type);
    var rows =
      '<tr><td>Site</td><td>' + esc(site.name) + '</td></tr>' +
      '<tr><td>Cooking type / cadence</td><td>' + esc(TYPE_LABEL[site.type]) + ' &mdash; NFPA-96 ' + esc(CADENCE[site.type].name) + ' cleaning</td></tr>' +
      '<tr><td>Visit date</td><td>' + esc($('hc-rep-date').value) + '</td></tr>' +
      '<tr><td>Technician</td><td>' + esc($('hc-rep-tech').value) + '</td></tr>' +
      '<tr><td>Grease depth &mdash; hood</td><td>' + esc($('hc-rep-hood').value) + '</td></tr>' +
      '<tr><td>Grease depth &mdash; duct</td><td>' + esc($('hc-rep-duct').value) + '</td></tr>' +
      '<tr><td>Grease depth &mdash; fan / exhaust</td><td>' + esc($('hc-rep-fan').value) + '</td></tr>' +
      '<tr><td>Deficiencies found</td><td>' + esc($('hc-rep-def').value || 'None') + '</td></tr>' +
      '<tr><td>Certificate / report #</td><td>' + esc($('hc-rep-cert').value) + '</td></tr>' +
      '<tr><td>Next cleaning due</td><td>' + (due ? esc(fmt(due)) : '-') + '</td></tr>';
    $('hc-printdoc').innerHTML =
      '<h1>Kitchen Exhaust Cleaning Service Report</h1>' +
      '<p>Per NFPA 96 &mdash; keep this report with your fire-safety records (3-year retention).</p>' +
      '<table><tbody>' + rows + '</tbody></table>' +
      '<p>&nbsp;</p><p>Technician signature: ______________________________&nbsp;&nbsp;&nbsp;&nbsp;Date: ____________</p>' +
      '<p>Customer signature: ______________________________&nbsp;&nbsp;&nbsp;&nbsp;Date: ____________</p>';
    window.print();
  }
  $('hc-addsite').addEventListener('click', function () { openForm(null); });
  $('hc-cancel').addEventListener('click', function () { $('hc-formwrap').hidden = true; });
  $('hc-report').addEventListener('click', openReport);
  $('hc-repcancel').addEventListener('click', function () { $('hc-reportwrap').hidden = true; });
  $('hc-form').addEventListener('submit', function (e) {
    e.preventDefault();
    var id = $('hc-id').value;
    var data = {
      id: id || newId(),
      name: $('hc-name').value.trim(),
      contact: $('hc-contact').value.trim(),
      phone: $('hc-phone').value.trim(),
      type: $('hc-type').value,
      last: $('hc-last').value,
      price: parseFloat($('hc-price').value) || 0
    };
    var sites = getSites();
    if (id) {
      for (var i = 0; i < sites.length; i++) if (sites[i].id === id) sites[i] = data;
    } else {
      sites.push(data);
    }
    setSites(sites);
    $('hc-formwrap').hidden = true;
    render();
  });
  $('hc-repform').addEventListener('submit', function (e) {
    e.preventDefault();
    printReport();
    var id = $('hc-rep-site').value;
    var sites = getSites();
    for (var i = 0; i < sites.length; i++) {
      if (sites[i].id === id) {
        sites[i].last = $('hc-rep-date').value;
        sites[i].lastCleaned = true;
      }
    }
    setSites(sites);
    $('hc-reportwrap').hidden = true;
    render();
  });
  $('hc-rows').addEventListener('click', function (e) {
    var btn = e.target.closest('button[data-act]');
    if (!btn) return;
    var act = btn.getAttribute('data-act');
    var id = btn.getAttribute('data-id');
    var sites = getSites();
    if (act === 'del') {
      if (!confirm('Delete this site?')) return;
      setSites(sites.filter(function (s) { return s.id !== id; }));
      render();
      return;
    }
    if (act === 'edit') { openForm(findSite(id)); return; }
    if (act === 'cleaned') {
      for (var i = 0; i < sites.length; i++) {
        if (sites[i].id === id) sites[i].last = iso(new Date());
      }
      setSites(sites);
      render();
    }
  });
  render();
})();
